# Manual linear interpolation for fossil ranges to all years
def lininterp(x_src, y_src, x_tgt):
    out = []
    for x in x_tgt:
        if x <= x_src[0]:
            out.append(y_src[0])
        elif x >= x_src[-1]:
            out.append(y_src[-1])
        else:
            for i in range(len(x_src)-1):
                if x_src[i] <= x <= x_src[i+1]:
                    t = (x - x_src[i]) / (x_src[i+1] - x_src[i])
                    out.append(y_src[i] + t * (y_src[i+1] - y_src[i]))
                    break
    return np.array(out)

gas_low_all = lininterp(fossil_years, gas_low, years)
gas_high_all = lininterp(fossil_years, gas_high, years)
coal_low_all = lininterp(fossil_years, coal_low, years)
coal_high_all = lininterp(fossil_years, coal_high, years)
